    html: "<label for=\"filter\" class=\"switch\" aria-label=\"Toggle Filter\">\r\n  <input type=\"checkbox\" id=\"filter\" />\r\n  <span>Latest</span>\r\n  <span>Popular</span>\r\n</label>\r\n\r\n<style>\r\n/* From Uiverse.io by cbolson  - Tags: switch */\r\n.switch {\r\n  --_switch-bg-clr: #70a9c5;\r\n  --_switch-padding: 4px; /* padding around button*/\r\n  --_slider-bg-clr: rgba(12, 74, 110, 0.65); /* slider color unchecked */\r\n  --_slider-bg-clr-on: rgba(12, 74, 110, 1); /* slider color checked */\r\n  --_slider-txt-clr: #ffffff;\r\n  --_label-padding: 1rem 2rem; /* padding around the labels -  this gives the switch it's global width and height */\r\n  --_switch-easing: cubic-bezier(\r\n    0.47,\r\n    1.64,\r\n    0.41,\r\n    0.8\r\n  ); /* easing on toggle switch */\r\n  color: white;\r\n  width: fit-content;\r\n  display: flex;\r\n  justify-content: center;\r\n  position: relative;\r\n  border-radius: 9999px;\r\n  cursor: pointer;\r\n  display: grid;\r\n  grid-template-columns: repeat(2, minmax(0, 1fr));\r\n  position: relative;\r\n  isolation: isolate;\r\n}\r\n\r\n.switch input[type=\"checkbox\"] {\r\n  position: absolute;\r\n  width: 1px;\r\n  height: 1px;\r\n  padding: 0;\r\n  margin: -1px;\r\n  overflow: hidden;\r\n  clip: rect(0, 0, 0, 0);\r\n  white-space: nowrap;\r\n  border-width: 0;\r\n}\r\n.switch > span {\r\n  display: grid;\r\n  place-content: center;\r\n  transition: opacity 300ms ease-in-out 150ms;\r\n  padding: var(--_label-padding);\r\n}\r\n.switch::before,\r\n.switch::after {\r\n  content: \"\";\r\n  position: absolute;\r\n  border-radius: inherit;\r\n  transition: inset 150ms ease-in-out;\r\n}\r\n/* switch slider */\r\n.switch::before {\r\n  background-color: var(--_slider-bg-clr);\r\n  inset: var(--_switch-padding) 50% var(--_switch-padding)\r\n    var(--_switch-padding);\r\n  transition:\r\n    inset 500ms var(--_switch-easing),\r\n    background-color 500ms ease-in-out;\r\n  z-index: -1;\r\n  box-shadow:\r\n    inset 0 1px 1px rgba(0, 0, 0, 0.3),\r\n    0 1px rgba(255, 255, 255, 0.3);\r\n}\r\n/* switch bg color */\r\n.switch::after {\r\n  background-color: var(--_switch-bg-clr);\r\n  inset: 0;\r\n  z-index: -2;\r\n}\r\n/* switch hover & focus */\r\n.switch:focus-within::after {\r\n  inset: -0.25rem;\r\n}\r\n.switch:has(input:checked):hover > span:first-of-type,\r\n.switch:has(input:not(:checked)):hover > span:last-of-type {\r\n  opacity: 1;\r\n  transition-delay: 0ms;\r\n  transition-duration: 100ms;\r\n}\r\n/* switch hover */\r\n.switch:has(input:checked):hover::before {\r\n  inset: var(--_switch-padding) var(--_switch-padding) var(--_switch-padding)\r\n    45%;\r\n}\r\n.switch:has(input:not(:checked)):hover::before {\r\n  inset: var(--_switch-padding) 45% var(--_switch-padding)\r\n    var(--_switch-padding);\r\n}\r\n/* checked - move slider to right */\r\n.switch:has(input:checked)::before {\r\n  background-color: var(--_slider-bg-clr-on);\r\n  inset: var(--_switch-padding) var(--_switch-padding) var(--_switch-padding)\r\n    50%;\r\n}\r\n/* checked - set opacity */\r\n.switch > span:last-of-type,\r\n.switch > input:checked + span:first-of-type {\r\n  opacity: 0.75;\r\n}\r\n.switch > input:checked ~ span:last-of-type {\r\n  opacity: 1;\r\n}\r\n\r\n</style>\r\n    ",
