    html: "<label class=\"switch\">\r\n\t<input type=\"checkbox\" class=\"chbox\">\r\n\t<div class=\"slider slider--0\">ON</div>\r\n\t<div class=\"slider slider--1\">\r\n\t\t<div></div>\r\n\t\t<div></div>\r\n\t</div>\r\n\t<div class=\"slider slider--2\"></div>\r\n\t<div class=\"slider slider--3\">OFF</div>\r\n</label>\r\n<style>\r\n/* From Uiverse.io by csemszepp - Source: codepen.io/narohan/pen/dyNwjJL - Tags: switch, checkbox, cool checkbox */\r\n.switch {\r\n  position: relative;\r\n  display: inline-block;\r\n  width: 80px;\r\n  height: 80px;\r\n  border: 2px solid #dcdcdc;\r\n  background: #e0e0e0;\r\n  box-shadow: 7px 7px 23px #bebebe, -7px -7px 23px #ffffff;\r\n  overflow: hidden;\r\n  border-radius: 60px;\r\n}\r\n\r\n.switch input {\r\n  opacity: 0;\r\n  width: 0;\r\n  height: 0;\r\n}\r\n\r\n.slider {\r\n  position: absolute;\r\n  cursor: pointer;\r\n  top: 0;\r\n  left: 0;\r\n  right: 0;\r\n  bottom: 0;\r\n  -webkit-transition: 0.5s;\r\n  transition: 0.5s;\r\n}\r\n\r\n.chbox:checked + .slider:before {\r\n  background: white;\r\n  box-shadow: none;\r\n}\r\n\r\n.chbox:focus + .slider {\r\n  box-shadow: 0 0 1px #2196f3;\r\n}\r\n\r\n.slider {\r\n  color: #9a9a9a;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 11px;\r\n  font-family: sans-serif;\r\n}\r\n\r\n.slider--0 {\r\n  color: white;\r\n  font-weight: 600;\r\n  background-color: #49d84e;\r\n}\r\n\r\n.slider--1 div {\r\n  transition: 0.5s;\r\n}\r\n\r\n.slider--1 div {\r\n  position: absolute;\r\n  width: 100%;\r\n  height: 50%;\r\n  left: 0;\r\n}\r\n\r\n.chbox:checked ~ .slider--1 div:first-child {\r\n  transform: translateY(-100%);\r\n  transition-delay: 1s;\r\n}\r\n\r\n.chbox:checked ~ .slider--1 div:last-child {\r\n  transform: translateY(100%);\r\n  transition-delay: 1s;\r\n}\r\n\r\n.chbox:checked ~ .slider--2 {\r\n  transform: translateX(100%);\r\n  transition-delay: 0.5s;\r\n}\r\n\r\n.chbox:checked ~ .slider--3 {\r\n  transform: translateX(-100%);\r\n  transition-delay: 0s;\r\n}\r\n\r\n.slider--1 div:first-child {\r\n  transform: translateY(0);\r\n  top: 0;\r\n  background-color: #f3f3f3;\r\n  transition-delay: 0s;\r\n}\r\n\r\n.slider--1 div:last-child {\r\n  transform: translateY(0);\r\n  bottom: 0;\r\n  background-color: #f3f3f3;\r\n  border-top: 1px solid #e0e0e0;\r\n  transition-delay: 0s;\r\n}\r\n\r\n.slider--2 {\r\n  background-color: #e6e6e6;\r\n  transition-delay: 0.5s;\r\n  transform: translateX(0);\r\n  border-left: 1px solid #d2d2d2;\r\n}\r\n\r\n.slider--3 {\r\n  background-color: #d2d2d2;\r\n  transition-delay: 1s;\r\n  transform: translatex(0);\r\n  border-right: 1px solid #d2d2d2;\r\n}\r\n\r\n</style>\r\n",
